import{_ as e,c as t,o as d,a2 as o}from"./chunks/framework.DdOM6S6U.js";const b=JSON.parse('{"title":"CMS configuration","description":"","frontmatter":{"sidebarPos":10,"sidebarTitle":"Configuration","sidebarGroupTitle":"Cms","outline":"deep"},"headers":[],"relativePath":"guide/cms/configuration.md","filePath":"guide/cms/configuration.md","lastUpdated":1787836208000}'),a={name:"guide/cms/configuration.md"},c=o('<h1 id="cms-configuration" tabindex="-1">CMS configuration <a class="header-anchor" href="#cms-configuration" aria-label="Permalink to &quot;CMS configuration&quot;">​</a></h1><p>Merged under <code>modularous.*</code> from <code>packages/modularous/config/merges/cms_*.php</code>. Host apps override via published config / <code>.env</code>.</p><h2 id="feature-switches" tabindex="-1">Feature switches <a class="header-anchor" href="#feature-switches" aria-label="Permalink to &quot;Feature switches&quot;">​</a></h2><table><thead><tr><th>Key</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>cms_features.enabled</code></td><td><code>true</code></td><td>Master CMS on/off</td></tr><tr><td><code>cms_features.register_contracts</code></td><td><code>true</code></td><td>Bind CMS contracts</td></tr><tr><td><code>cms_features.register_middlewares</code></td><td><code>true</code></td><td>Register CMS middleware aliases</td></tr></tbody></table><h2 id="routing-urls" tabindex="-1">Routing &amp; URLs <a class="header-anchor" href="#routing-urls" aria-label="Permalink to &quot;Routing &amp; URLs&quot;">​</a></h2><table><thead><tr><th>Key</th><th>Purpose</th></tr></thead><tbody><tr><td><code>cms_routing.*</code></td><td>Catch-all, universal front, localization, domain, signed preview, visitor redirects, UrlRoute cache/resync</td></tr><tr><td><code>cms_routing.public_front_catch_all_exclude_path_prefixes</code></td><td>Extra path prefixes the catch-all must ignore — see <a href="./public-routing">Public routing</a></td></tr><tr><td><code>cms_parent_segments.*</code></td><td>Enable ParentSegment URL prefix bindings</td></tr></tbody></table><h2 id="presentation-defaults-that-matter" tabindex="-1">Presentation (defaults that matter) <a class="header-anchor" href="#presentation-defaults-that-matter" aria-label="Permalink to &quot;Presentation (defaults that matter)&quot;">​</a></h2><p>Read in dependency order: <a href="./stylesheets">Stylesheets</a> → <a href="./layout-builders">Layout builders</a> → <a href="./page-layouts">Page layouts</a>.</p><h3 id="cms-stylesheets" tabindex="-1"><code>cms_stylesheets</code> <a class="header-anchor" href="#cms-stylesheets" aria-label="Permalink to &quot;`cms_stylesheets`&quot;">​</a></h3><table><thead><tr><th>Key</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>compiled_disk</code></td><td><code>local</code></td><td>Disk for compiled CSS</td></tr><tr><td><code>compiled_directory</code></td><td><code>modularous/cms/stylesheets</code></td><td>Path on that disk</td></tr><tr><td><code>utilities_class_prefix</code></td><td><code>u-</code></td><td>Utility class namespace</td></tr><tr><td><code>scssphp.enabled</code></td><td><code>false</code></td><td>SCSS compile</td></tr><tr><td><code>public_route.enabled</code></td><td><code>true</code></td><td>Serve <code>/{prefix}/{slug}.css</code></td></tr><tr><td><code>public_route.path_prefix</code></td><td><code>cms/stylesheets</code></td><td>Public URL prefix</td></tr><tr><td><code>public_route.cache_bust_query</code></td><td><code>true</code></td><td><code>?v=&lt;hash&gt;</code> on bundle links</td></tr></tbody></table><p>Details: <a href="./stylesheets">Stylesheets</a>.</p><h3 id="cms-layout-builder" tabindex="-1"><code>cms_layout_builder</code> <a class="header-anchor" href="#cms-layout-builder" aria-label="Permalink to &quot;`cms_layout_builder`&quot;">​</a></h3><table><thead><tr><th>Key</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>default_blade_source</code></td><td><strong><code>db</code></strong></td><td>Used when LayoutBuilder <strong>or</strong> PageLayout omits <code>blade_source</code> (<code>MODULAROUS_CMS_LAYOUT_BLADE_SOURCE</code>)</td></tr><tr><td><code>max_blade_segments_bytes</code></td><td><code>512000</code></td><td>DB segment size cap</td></tr><tr><td><code>preview_enabled</code></td><td><code>true</code></td><td>Admin layout preview</td></tr><tr><td><code>middleware_enabled</code></td><td><code>false</code></td><td>Opt-in <code>?cms_layout=</code> middleware</td></tr><tr><td><code>middleware_query_slug_key</code></td><td><code>cms_layout</code></td><td>Query key</td></tr><tr><td><code>default_layout_slug</code></td><td><code>&#39;&#39;</code></td><td>Fallback LayoutBuilder slug for middleware / PageLayout default shell</td></tr></tbody></table><p>Filesystem blades: <a href="./layout-builders">Layout builders</a> — slug theme pack <code>resources/views/cms/layout_builder/{slug}/</code> (<code>cms.layout_builder.{slug}.*</code>; <code>blade_view_name</code> often NULL). Optional master via <code>cms:layout-builder:publish-blades</code>.</p><h3 id="cms-page-layouts" tabindex="-1"><code>cms_page_layouts</code> <a class="header-anchor" href="#cms-page-layouts" aria-label="Permalink to &quot;`cms_page_layouts`&quot;">​</a></h3><table><thead><tr><th>Key</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>true</code></td><td>Feature on/off</td></tr><tr><td><code>filesystem_segments_without_db_binding_enabled</code></td><td><strong><code>true</code></strong></td><td>Merge module <code>page_layout/*</code> blades without a DB PageLayout row</td></tr><tr><td><code>default_layout_builder_id</code></td><td><code>null</code></td><td>Else use <code>cms_layout_builder.default_layout_slug</code></td></tr><tr><td><code>layout_appends_modal_preview_enabled</code></td><td><code>true</code></td><td>Appends modal preview</td></tr><tr><td><code>public_presentation_informational_fallback_enabled</code></td><td><code>true</code></td><td>Inner body fallback</td></tr><tr><td><code>public_presentation_informational_fallback_view</code></td><td><code>cms::page.page_layout.body</code></td><td>Fallback view</td></tr></tbody></table><p>Filesystem appends: <a href="./page-layouts">Page layouts</a> — <code>{module}::{route}.page_layout.{segment}</code> → <code>modules/{Module}/Resources/views/{route}/page_layout/</code> (<code>blade_view_name</code> often NULL).</p><h2 id="seo-sitemap" tabindex="-1">SEO &amp; sitemap <a class="header-anchor" href="#seo-sitemap" aria-label="Permalink to &quot;SEO &amp; sitemap&quot;">​</a></h2><table><thead><tr><th>Key</th><th>Purpose</th></tr></thead><tbody><tr><td><code>cms_sitemap.*</code></td><td><code>/sitemap.xml</code> + <code>/sitemap.xsl</code>, cache key, defaults, build-on-miss, panel step-up</td></tr><tr><td><code>cms_seo.*</code></td><td>Canonical helpers, robots.txt, llms.txt, staging noindex, admin soft warnings</td></tr></tbody></table><h2 id="other" tabindex="-1">Other <a class="header-anchor" href="#other" aria-label="Permalink to &quot;Other&quot;">​</a></h2><table><thead><tr><th>Key</th><th>Purpose</th></tr></thead><tbody><tr><td><code>cms_settings.*</code></td><td>CMS settings cache TTL / sensitive keys</td></tr><tr><td><code>cms_schedule.*</code></td><td>Publish-window boundary scan</td></tr><tr><td><code>cms_promotion.*</code></td><td>Staging→prod promotion workflow</td></tr></tbody></table><p>Toggle individual public endpoints via flags used by <code>CmsPublicSystemRoutes</code> (e.g. <code>cms_sitemap.route_enabled</code>, <code>cms_seo.robots.route_enabled</code>, <code>cms_seo.llms.route_enabled</code>, <code>cms_routing.signed_preview.enabled</code>, <code>cms_stylesheets.public_route.enabled</code>).</p>',22),r=[c];function s(l,i,u,n,h,_){return d(),t("div",null,r)}const p=e(a,[["render",s]]);export{b as __pageData,p as default};
